#include <cstdlib>
#include <iostream>

void log_close() { std::cout << "Cleanup 2: Closing log file.\n"; }
void db_disconnect() { std::cout << "Cleanup 1: Disconnecting DB.\n"; }

int main() {
    // Register 1st (runs last)
    if (std::atexit(db_disconnect) != 0) {
        std::cerr << "Failed to register DB cleanup.\n";
        return EXIT_FAILURE;
    }

    // Register 2nd (runs first)
    if (std::atexit(log_close) != 0) {
        std::cerr << "Failed to register log cleanup.\n";
        return EXIT_FAILURE;
    }

    // Program ends, handlers run in reverse order (log_close then db_disconnect)
    return EXIT_SUCCESS;
}
